public double trimMean(int[] arr) {
    if (arr == null || arr.length == 0) {
        throw new IllegalArgumentException("Array must not be null or empty");
    }

    int n = arr.length;
    int trimSize = (int) Math.round(n * 0.05);

    if (trimSize == 0) {
        // If 5% of the array length is less than 1, return the mean of the whole array
        double sum = 0;
        for (int num : arr) {
            sum += num;
        }
        return sum / n;
    }

    java.util.Arrays.sort(arr);

    double sum = 0;
    for (int i = trimSize; i < n - trimSize; i++) {
        sum += arr[i];
    }

    return sum / (n - 2 * trimSize);
}

