            // Check if there is a consecutive ')' to match with the current ')'
            if (i + 1 < s.length() && s.charAt(i + 1) == ')') {
                i++; // Skip the next ')' as it is matched
            } else {
                // If no consecutive ')', we need an insertion to balance
                insertions++;
            }
        }
    }
    // Add remaining unmatched '(' with corresponding ')'
    insertions += open * 2;
    return insertions;
}

